    'co.tab': 'Roles from HR',
    'co.leadOnly': 'Only the vault is loaded, so there is no access to explain yet \u2014 but the conditions of a rule set are already in the contracts of the {people} people. Which departments, job titles and locations exist, and how they combine, is mined here; entitlements attach once a reconciliation is imported.',
    'co.kPlaced': 'People placed',
    'co.kRoles': 'Candidate roles',
    'co.noCap': 'no cap',
    'co.floor': 'Share a rule when still alike \u2265',
    'co.knobsNote': 'Smallest group and rule cap are shared with the pyramid. Sibling groups merge into one \u201cone of\u201d rule as long as the merged rule stays at least this alike, and a rule on two or more attributes below it is never proposed, however many people it would place \u2014 a single-attribute root may sit below it, its alikeness is what the rules on top of it improve; a group too small on its own is placed by joining its siblings.',
    'co.proposalTitle': 'Proposed rule set',
    'co.proposalNote': 'No access model uses one attribute, so this is built as a set. Every merged rule from every combination is a candidate; rules are taken layer by layer \u2014 every single-attribute rule worth a slot first, then the two-attribute rules that add something on top of them, then three \u2014 each by how much more alike it makes the people it covers than the rules already taken do. The cap is a depth budget spent from the top of that pyramid, so it cuts drill-down evenly instead of spending its slots on one job title. The mix \u2014 titles here, department and title there, department underneath \u2014 is what the data supports. A person counts double when they joined, moved or left in the last year \u2014 that is where a rule pays \u2014 and half when their job title is in the long tail \u2014 the titles outside the ones that hold 80% of people, which fit self-service better than rules. A \u201cone of\u201d list that covers nearly every value collapses to the wider rule, and each rule is shown under the wider rule it builds on \u2014 the pyramid, without the access side.',
    'co.kRulesOfCap': '{n} of {cap}',
    'co.kRulesAll': 'everything worth a slot fits \u2014 {lists} rules carry a \u201cone of\u201d list',
    'co.kRulesMore': '{over} more would still add something \u2014 {lists} rules within the cap carry a \u201cone of\u201d list',
    'co.kAlikeSetFoot': 'how much of what decides access is pinned down for each person by their most specific rule, averaged over everyone \u2014 unplaced people count as 0',
    'co.kFit': 'Role fit',
    'co.kFitValue': '{k} of {n} job titles',
    'co.kFitOrg': 'The departments form a hierarchy {depth} levels deep; each level is offered as an attribute, and a rule on a branch exports as the list of departments beneath it.',
    'co.orgLevel': 'Department level {n}',
    'co.orgFollows': 'follows Department',
    'co.kFitFoot': 'hold 80% of people; a typical person shares their title with {typical} others; departments: {kd} of {nd} hold 80%. The other {tail} people are the long tail, {fl} joined, moved or left last year. Few titles for most people fits roles; many means self-service does the rest.',
    'co.kPlacedSplit': 'core jobs {core} \u00b7 long tail {tail} \u00b7 joined, moved or left last year {fl}',
    'co.mixNote': 'This proposal: {mix} \u2014 {n} roots, {m} rules build on them.',
    'co.pillTail': 'long tail',
    'co.pillTailTip': '{pct} of these people are in job titles outside the core \u2014 self-service may fit better than a rule',
    'co.pillFlowTip': '{pct} joined, moved or left in the last year',
    'co.kMixNone': 'no rule clears the bar \u2014 lower the smallest group or the alike floor',
    'co.attrsTitle': 'Attributes',
    'co.attrsNote': 'What may condition a rule, what must be in every rule, and how much each attribute decides access. A cost centre per person is switched off by the data; a job title is something you may want to insist on.',
    'co.cUse': 'Use',
    'co.cRequire': 'In every rule',
