    'co.searchRoles': 'Search roles\u2026',
    'co.showAll': 'Show all {n} roots',
    'co.forestNote': 'Each block is a generic rule with the rules that build on it; bar length is people, tone is how alike they are. A \u201clong tail\u201d pill marks a rule mostly over job titles outside the core, \u21c4 one over people who came, moved or left last year. Click a bar for its people.',
    'co.cDecides': 'Decides access',
