    'fi.vault-attribute-gap.title': 'People missing an attribute their colleagues have',
    'fi.vault-attribute-gap.what': '{n} contract attribute value(s) are empty where the organisation fills them almost everywhere: {facets}.',
    'fi.vault-attribute-gap.why': 'A rule condition on that attribute cannot select these people, so they silently fall outside every rule written against it \u2014 and nothing reports that as an error.',
    'fi.vault-attribute-gap.fix': 'Correct them in the source system; a fill rate this high means the field is maintained and these are omissions rather than policy.',
    'fi.vault-attribute-gap.detail': '{facet} empty ({fill} of colleagues have it)',
    'fi.vault-dead-title.title': 'Job titles that exist only on ended contracts',
    'fi.vault-dead-title.what': '{n} job title(s) appear only on contracts that have ended.',
    'fi.vault-dead-title.why': 'A rule conditioned on one of these will never match anybody again, so it stays in the model looking active while granting nothing.',
    'fi.vault-dead-title.fix': 'Check whether the title was renamed \u2014 if so, the rules pointing at the old name need repointing \u2014 or retire it.',
    'fi.vault-dead-title.detail': '{n} ended contracts, last on {date}',
