    'fi.vault-no-manager.why': 'Approvals, reviews and escalations are routed to a manager; where none is named, that routing has nowhere to go.',
    'fi.vault-no-manager.fix': 'Fill the manager on the department or on its contracts in the source system.',
    'fi.vault-no-manager.detail': '{n} people',
