    'fi.vault-undeclared-department.why': 'A rule author picks departments from that list, so these cannot be addressed by a condition even though people work there.',
    'fi.vault-undeclared-department.fix': 'Check the source system\u2019s department feed; a department present on contracts and absent from the structure is usually a synchronisation gap.',
    'fi.vault-undeclared-department.detail': '{n} people',
