    'fi.vault-no-contract.why': 'Every business rule condition reads from a contract, so these people match nothing \u2014 including the rules that would have given them their access.',
    'fi.vault-no-contract.fix': 'Check whether they are pre-hires the feed has not delivered yet, or records that should have been removed.',
    'fi.vault-no-contract.detail': 'no contracts in the export',
