    'ro.pyramidNote': 'Mining, which ignores the rules above and starts from the access',
    'ro.pyramidLead': 'With people and contracts available, rules are mined against the organisation\u2019s own attributes instead of guessed from what appears together: {rules} rules over {levels}, granting {grants} entitlements and explaining {coverage} of all access. Each one already carries the condition that selects its group, and rules stack, so nothing granted higher up is repeated below.',
