    'bd.methodLead': 'The analysis uses a single source: the reconciliation export from HelloID, which places what exists in the target system next to what the identity system is supposed to drive.',
    'bd.method1': 'Every line in the export is reduced to three kinds of object: accounts, access groups and people. Lines do not weigh the same — an account without an owner counts for far more than one extra group membership.',
    'bd.method2': 'The overall assessment (0–100) combines three things: how risky accounts are on average, what share of accounts falls in the highest risk classes, and how many accounts have no owner.',
    'bd.method3': 'Cost is calculated per licence-bearing group times its membership. Groups with no price count as zero, so the amounts are a lower bound.',
    'bd.method4': 'No personal data left the device: the analysis runs entirely locally in the browser.',
    'bd.method5': 'The statements in this report describe what the export shows. Anything that depends on processes or administration outside it — licence billing, exemptions, contract end dates — is named as something to check, not assumed.',
    'bd.methodFoot': 'Prices, sensitivities and weights are configurable assumptions, not vendor data. Check them against the contract before sharing amounts outside the organisation.',


