    'bd.ac.model': 'Write rules for the access that has none',
    'bd.ac.model.why': '{share} of the access handed out today is described by no rule, so it stays outside the identity process by default.',
    'bd.method6': 'Where a business-rule export was supplied, it is compared against the same reconciliation data: a group counts as described when any rule grants it. The conditions inside those rules are read but not evaluated, because that needs personnel data neither export contains.',
    'bd.method7': 'The governance score on the cover is one number, higher is better: half is how little risk sits in the accounts (100 minus the risk exposure, which itself weighs account risk, the share of accounts at high risk and how many accounts have an owner), half is the share of compliance controls met, weighted by severity. Every other figure in this report is one of its parts and says which way is better.',
    'bd.th.external': 'Suppliers and contractors',
