    'py.tab.gaps': 'Gaten en uitschieters',
    'co.tab': 'Rollen uit HR',
    'co.leadOnly': 'Alleen de vault is geladen, dus er is nog geen toegang om te verklaren \u2014 maar de condities van een regelset zitten al in de contracten van de {people} mensen. Welke afdelingen, functies en locaties er zijn en hoe ze samengaan wordt hier gedolven; rechten komen erbij zodra een reconciliatie is ge\u00efmporteerd.',
    'co.kPlaced': 'Mensen geplaatst',
    'co.kRoles': 'Kandidaatrollen',
    'co.noCap': 'geen limiet',
    'co.floor': 'Deel een regel als nog gelijkend \u2265',
    'co.knobsNote': 'Kleinste groep en regellimiet zijn gedeeld met de piramide. Naburige groepen gaan samen in een \u201ceen van\u201d-regel zolang de samengevoegde regel minstens zo gelijkend blijft, en een regel op twee of meer attributen eronder wordt nooit voorgesteld, hoeveel mensen ze ook zou plaatsen \u2014 een wortel op \u00e9\u00e9n attribuut mag eronder zitten, haar gelijkendheid is wat de regels erbovenop verbeteren; een groep die alleen te klein is wordt geplaatst door bij haar buren aan te sluiten.',
    'co.proposalTitle': 'Voorgestelde regelset',
    'co.proposalNote': 'Geen enkel toegangsmodel gebruikt \u00e9\u00e9n attribuut, dus dit wordt als set gebouwd. Elke samengevoegde regel uit elke combinatie is kandidaat; regels worden laag voor laag gekozen \u2014 eerst elke regel op \u00e9\u00e9n attribuut die een plek waard is, dan de regels op twee attributen die daar iets aan toevoegen, dan drie \u2014 elk op hoeveel gelijkender ze de mensen maken die ze dekken dan de al gekozen regels doen. De limiet is een dieptebudget dat vanaf de top van die piramide wordt besteed, dus ze snijdt het uitdiepen gelijkmatig af in plaats van alle plekken aan \u00e9\u00e9n functie te geven. De mix \u2014 hier functies, daar afdeling met functie, afdeling eronder \u2014 is wat de gegevens dragen. Iemand telt dubbel als die in het afgelopen jaar is gekomen, verhuisd of vertrokken \u2014 daar betaalt een regel zich uit \u2014 en half als de functie in de lange staart zit \u2014 de functies buiten de functies die 80% van de mensen houden, die beter bij selfservice passen dan bij regels. Een \u201ceen van\u201d-lijst die bijna elke waarde dekt valt terug op de bredere regel, en elke regel staat onder de bredere regel waarop ze bouwt \u2014 de piramide, zonder de toegangskant.',
    'co.kRulesOfCap': '{n} van {cap}',
    'co.kRulesAll': 'alles wat een plek waard is past \u2014 {lists} regels dragen een \u201ceen van\u201d-lijst',
    'co.kRulesMore': '{over} meer zouden nog iets toevoegen \u2014 {lists} regels binnen de limiet dragen een \u201ceen van\u201d-lijst',
    'co.kAlikeSetFoot': 'hoeveel van wat toegang bepaalt per persoon is vastgelegd door de meest specifieke regel, gemiddeld over iedereen \u2014 ongeplaatste mensen tellen als 0',
    'co.kFit': 'Rolgeschiktheid',
    'co.kFitValue': '{k} van {n} functies',
    'co.kFitOrg': 'De afdelingen vormen een hi\u00ebrarchie van {depth} niveaus; elk niveau wordt als attribuut aangeboden, en een regel op een tak exporteert als de lijst afdelingen eronder.',
