    'fi.nedap-uncovered.why': 'De HelloID Nedap-connector kent bereik toe op basis van deze regels; wie op geen regel matcht krijgt geen teams en geen locaties — inloggen lukt, maar er is niets te zien, en niemand wordt gewaarschuwd.',
    'fi.nedap-uncovered.fix': 'Voeg mappingregels toe voor hun afdeling/functie-combinaties in de Nedap ONS-werkbank, of een afdelingsbrede wildcardregel waar dat de bedoeling is.',
    'fi.nedap-unresolved.title': 'Nedap-mappingnamen die de opzoeklijsten niet kunnen herleiden',
