    'fi.nedap-unresolved.why': 'De connector-CSV\'s bevatten ID\'s; een regel met een onherleidbare naam valt uit de export en het recht komt stilzwijgend nooit in Nedap aan.',
    'fi.nedap-unresolved.fix': 'Herstel de spelling in de mappingregel of vul de opzoeklijst aan, en exporteer de CSV\'s opnieuw.',
    'fi.nedap-lint.title': 'Nedap-mappingregels die aandacht vragen',
    'fi.nedap-lint.what': '{n} mappingregel(s) zijn overbodig, dubbel, conflicterend of onbekend in de geïmporteerde HR-data.',
    'fi.nedap-lint.why': 'Elk ervan is een regel die niet doet wat de auteur bedoelde: hij kent niets toe, wordt opgeslokt door een wildcard, of verwijst naar een afdeling of functie die HR niet kent.',
    'fi.nedap-lint.fix': 'Loop ze na op het gezondheid-tabblad van de Nedap ONS-werkbank; de melding per regel zegt wat er moet veranderen.',

    'fi.privileged-orphan.title': 'Actieve accounts met beheerrechten zonder eigenaar',
    'fi.privileged-orphan.what': '{n} actieve account(s) zitten in beheer-, PAM- of servergroepen maar zijn niet gekoppeld aan een medewerker in HelloID.',
    'fi.privileged-orphan.why': 'Er is geen medewerker aan deze accounts gekoppeld, dus geen enkele gebeurtenis in het dienstverband zet een controle of intrekking van deze beheerrechten in gang, en gebruik ervan is uit deze gegevens niet te herleiden tot een persoon.',
    'fi.privileged-orphan.fix': 'Leg per account een eigenaar vast, of breng het onder in een beheerd serviceaccountproces. Is er geen eigenaar vast te stellen, beslis dan expliciet of het account actief mag blijven.',

    'fi.enabled-orphan.title': 'Actieve accounts die niet door HelloID worden beheerd',
    'fi.enabled-orphan.what': '{n} actieve account(s) bestaan in het doelsysteem zonder gekoppelde medewerker.',
    'fi.enabled-orphan.why': 'Deze accounts kunnen inloggen, maar er is geen medewerker aan gekoppeld in HelloID, dus er is geen instroom-, doorstroom- of uitstroommoment dat op ze van toepassing is.',
    'fi.enabled-orphan.fix': 'Koppel aan een medewerker, maak er een beheerd serviceaccount van, of schakel uit. Zet de afhandeling in de reconciliatie op Uitgesloten voor accounts die terecht buiten scope vallen.',

    'fi.external-accounts.title': 'Actieve leveranciers- en inhuuraccounts',
