    'fi.external-accounts.why': 'De accountnaam wijst op een partij buiten de organisatie. Deze export laat niet zien of daar ergens een einddatum voor is vastgelegd.',
    'fi.external-accounts.fix': 'Controleer per account of de opdracht nog loopt, en leg waar dat zo is een einddatum en een interne contactpersoon vast waar HelloID op kan sturen.',

    'fi.test-accounts.title': 'Actieve test- en demo-accounts',
    'fi.test-accounts.what': '{n} actieve account(s) lijken test- of demo-identiteiten.',
    'fi.test-accounts.why': 'De naamgeving wijst op een tijdelijk doel, maar deze export laat niet zien waar deze accounts voor worden gebruikt of dat ze nog nodig zijn.',
    'fi.test-accounts.fix': 'Stel per account het huidige doel vast; is dat vervallen, schakel het account dan uit.',

    'fi.service-unmanaged.title': 'Serviceaccounts buiten het IAM-model',
    'fi.service-unmanaged.what': '{n} serviceaccount(s) hebben geen geregistreerde eigenaar.',
    'fi.service-unmanaged.why': 'Voor deze accounts is geen eigenaar vastgelegd, dus deze export kan niet laten zien met wie moet worden overlegd voordat hun wachtwoord of rechten wijzigen.',
    'fi.service-unmanaged.fix': 'Registreer per account een verantwoordelijk team en een vastgelegd doel; sluit ze expliciet uit van reconciliatie op persoon.',

    'fi.disabled-licensed.title': 'Uitgeschakelde accounts die nog betaalde licenties gebruiken',
