    'fi.disabled-entitled.why': 'De lidmaatschappen blijven op het account staan, dus opnieuw activeren geeft dezelfde toegang terug zonder dat er een nieuwe toekenning wordt vastgelegd.',
    'fi.disabled-entitled.fix': 'Verwijder groepslidmaatschappen bij het uitschakelen en leg vast wat is weggehaald.',

    'fi.privileged-unmanaged.title': 'Beheergroepen toegekend buiten het IAM-model',
