    'fi.privileged-unmanaged.why': 'Deze lidmaatschappen komen niet uit een HelloID business rule, dus HelloID kent ze niet opnieuw toe en trekt ze ook niet in als de functie van iemand wijzigt.',
    'fi.privileged-unmanaged.fix': 'Beslis per groep of die als HelloID-recht met een business rule wordt gemodelleerd, of via een aanvraagproces daarbuiten wordt afgehandeld.',

    'fi.security-control-gap.title': 'Beveiligingsbasis niet bij elke actieve gebruiker toegepast',
